    private static void requireExists(Connection con,String table,String where,Object a,Object b)throws SQLException{try(PreparedStatement ps=con.prepareStatement("SELECT 1 FROM "+table+" WHERE "+where)){ps.setObject(1,a);ps.setObject(2,b);try(ResultSet rs=ps.executeQuery()){if(!rs.next())throw new IllegalArgumentException("Referenced record not found.");}}}
    private void validateUser(Connection con,int t,int u)throws SQLException{requireExists(con,"dbo.Users","Id=? AND ShaleClientId=? AND ISNULL(is_deleted,0)=0",u,t);} private static void touchCase(Connection con,long caseId,int t)throws SQLException{try(PreparedStatement ps=con.prepareStatement("UPDATE dbo.Cases SET UpdatedAt=SYSUTCDATETIME() WHERE Id=? AND ShaleClientId=?")){ps.setLong(1,caseId);ps.setInt(2,t);ps.executeUpdate();}}
    private static void verifyTenant(Connection con,int t)throws SQLException{try(PreparedStatement ps=con.prepareStatement("SELECT CAST(SESSION_CONTEXT(N'ShaleClientId') AS INT)");ResultSet rs=ps.executeQuery()){if(!rs.next()||rs.getInt(1)!=t)throw new IllegalStateException("ShaleClientId session context mismatch.");}}
    private static void assertRowVer(byte[] a,byte[] e){if(!Arrays.equals(a,e))throw new IllegalStateException("Material item changed.");} private static void requireRowVer(byte[] rv){if(rv==null||rv.length==0)throw new IllegalArgumentException("expectedRowVer is required.");}
    private static RuntimeException sqlFailure(SQLException e){return new IllegalStateException("Database operation failed.",e);} private static void rollback(Connection c){try{c.rollback();}catch(Exception ignored){}}
    private static String norm(String s){return s==null?null:s.trim().toUpperCase(Locale.ROOT);} private static String blank(String s){return s==null||s.trim().isEmpty()?null:s.trim();}
    private static LocalDateTime ldt(ResultSet rs,String c)throws SQLException{Timestamp t=rs.getTimestamp(c);return t==null?null:t.toLocalDateTime();} private static LocalDate ld(ResultSet rs,String c)throws SQLException{java.sql.Date d=rs.getDate(c);return d==null?null:d.toLocalDate();}
    private static void setTs(PreparedStatement ps,int i,LocalDateTime v)throws SQLException{if(v==null)ps.setNull(i,Types.TIMESTAMP);else ps.setTimestamp(i,Timestamp.valueOf(v));} private static void setDate(PreparedStatement ps,int i,LocalDate v)throws SQLException{if(v==null)ps.setNull(i,Types.DATE);else ps.setDate(i,java.sql.Date.valueOf(v));} private static void setInt(PreparedStatement ps,int i,Integer v)throws SQLException{if(v==null)ps.setNull(i,Types.INTEGER);else ps.setInt(i,v);} private static void setLong(PreparedStatement ps,int i,Long v)throws SQLException{if(v==null)ps.setNull(i,Types.BIGINT);else ps.setLong(i,v);} 
